/** static void LinkTest_PrintHex(u32 num, u8 x, u8 y, u8 length) */
export function LinkTest_PrintHex(num: any, x: any, y: any, length: any): any {
  let buff: any = [];
      let i: any = null;

      for (i = 0; i < length; i++)
      {
          buff[i] = num & 0xF;
          num >>= 4;
      }
      for (i = length - 1; i >= 0; i--)
      {
          LinkTest_PrintNumChar(buff[i], x, y);
          x++;
      }
}

/** static void LinkTest_PrintString(const char *str, u8 x, u8 y) */
export function LinkTest_PrintString(str: any, x: any, y: any): any {
  let xOffset: any = null;
      let i: any = null;
      let yOffset: any = null;

      yOffset = 0;
      xOffset = 0;
      for (i = 0; str[i] != 0; str++)
      {
          if (str[i] == "\n".charCodeAt(0))
          {
              yOffset++;
              xOffset = 0;
          }
          else
          {
              LinkTest_PrintChar(str[i], x + xOffset, y + yOffset);
              xOffset++;
          }
      }
}

