/** void CB2_LinkError(void) */
export function CB2_LinkError(): any {
  let tilemapBuffer: any = null;

      SetGpuReg(REG_OFFSET_DISPCNT, 0);
      m4aMPlayStop(gMPlayInfo_SE1);
      m4aMPlayStop(gMPlayInfo_SE2);
      m4aMPlayStop(gMPlayInfo_SE3);
      InitHeap(gHeap, (0x1C000));
      ResetSpriteData();
      FreeAllSpritePalettes();
      ResetPaletteFadeControl();
      SetBackdropFromColor((RGB(0, 0, 0)));
      ResetTasks();
      ScanlineEffect_Stop();
      if (gWirelessCommType)
      {
          if (!sLinkErrorBuffer.disconnected)
              gWirelessCommType = 3;

          ResetLinkRfuGFLayer();
      }
      SetVBlankCallback(VBlankCB_LinkError);
      ResetBgsAndClearDma3BusyFlags(0);
      InitBgsFromTemplates(0, sLinkErrorBgTemplates, ARRAY_COUNT(sLinkErrorBgTemplates));
      sLinkErrorBgTilemapBuffer = tilemapBuffer = Alloc(BG_SCREEN_SIZE);
      SetBgTilemapBuffer(1, tilemapBuffer);
      if (InitWindows(sLinkErrorWindowTemplates))
      {
          DeactivateAllTextPrinters();
          ResetTempTileDataBuffers();
          SetGpuReg(REG_OFFSET_BLDCNT, 0);
          SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          SetGpuReg(REG_OFFSET_BG0HOFS, 0);
          SetGpuReg(REG_OFFSET_BG0VOFS, 0);
          SetGpuReg(REG_OFFSET_BG1HOFS, 0);
          SetGpuReg(REG_OFFSET_BG1VOFS, 0);
          ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_WIN1_ON | DISPCNT_OBJWIN_ON);
          LoadPalette(gStandardMenuPalette, BG_PLTT_ID(15), PLTT_SIZE_4BPP);
          gSoftResetDisabled = FALSE;
          CreateTask(Task_DestroySelf, 0);
          StopMapMusic();
          gMain.callback1 = NULL;
          RunTasks();
          AnimateSprites();
          BuildOamBuffer();
          UpdatePaletteFade();
          SetMainCallback2(CB2_PrintErrorMessage);
      }
}

/** static void ErrorMsg_MoveCloserToPartner(void) */
