/** static void CB2_PrintErrorMessage(void) */
export function CB2_PrintErrorMessage(): any {
  switch (gMain.state)
      {
          case 0:
               
               
              if (sLinkErrorBuffer.disconnected)
                  ErrorMsg_MoveCloserToPartner();
              else
                  ErrorMsg_CheckConnections();
              break;
          case 2:
              ShowBg(0);
              if (sLinkErrorBuffer.disconnected)
                  ShowBg(1);
              break;
          case  30:
              PlaySE((22));
              break;
          case  60:
              PlaySE((22));
              break;
          case  90:
              PlaySE((22));
              break;
          case 130:
              if (gWirelessCommType == 2)
                  AddTextPrinterParameterized3(WIN_LINK_ERROR_TOP, FONT_SHORT_COPY_1, 2, 20, sTextColors, 0, gText_ABtnTitleScreen);
              else if (gWirelessCommType == 1)
                  AddTextPrinterParameterized3(WIN_LINK_ERROR_TOP, FONT_SHORT_COPY_1, 2, 20, sTextColors, 0, gText_ABtnRegistrationCounter);
              break;
      }
      if (gMain.state == 160)
      {
          if (gWirelessCommType == 1)
          {
              if (JOY_NEW(A_BUTTON))
              {
                  PlaySE((21));
                  gWirelessCommType = 0;
                  sLinkErrorBuffer.disconnected = FALSE;
                  ReloadSave();
              }
          }
          else if (gWirelessCommType == 2)
          {
              if (JOY_NEW(A_BUTTON))
              {
                  rfu_REQ_stopMode();
                  rfu_waitREQComplete();
                  DoSoftReset();
              }
          }
      }

      if (gMain.state != 160)
          gMain.state++;
}

