/** bool8 HandleLinkConnection(void) */
export function HandleLinkConnection(): any {
  let main1Failed, main2Failed;

      if (gWirelessCommType == 0)
      {
          gLinkStatus = LinkMain1(gShouldAdvanceLinkState, gSendCmd, gRecvCmds);
          LinkMain2(gMain.heldKeys);
          if ((gLinkStatus & (0x00000100)) && IsSendingKeysOverCable() == TRUE)
              return TRUE;
      }
      else
      {
          main1Failed = RfuMain1();  
          main2Failed = RfuMain2();
          if (IsSendingKeysOverCable() == TRUE)
          {
               
               
              if (main1Failed == TRUE || IsRfuRecvQueueEmpty() || main2Failed)
                  return TRUE;
          }
      }
      return FALSE;
}

