/** static void DisableSerial(void) */
export function DisableSerial(): any {
  DisableInterrupts(INTR_FLAG_TIMER3 | INTR_FLAG_SERIAL);
      REG_SIOCNT = SIO_MULTI_MODE;
      /* transpiler bug : REG_TMCNT_H(3) = 0; */ ;
      REG_IF = INTR_FLAG_TIMER3 | INTR_FLAG_SERIAL;
      REG_SIOMLT_SEND = 0;
      REG_SIOMLT_RECV = 0;
      CpuFill32(0,gLink, 0);
}

/** static void EnableSerial(void) */
export function EnableSerial(): any {
  DisableInterrupts(INTR_FLAG_TIMER3 | INTR_FLAG_SERIAL);
      REG_RCNT = 0;
      REG_SIOCNT = SIO_MULTI_MODE;
      REG_SIOCNT |= SIO_115200_BPS | SIO_INTR_ENABLE;
      EnableInterrupts(INTR_FLAG_SERIAL);
      REG_SIOMLT_SEND = 0;
      CpuFill32(0,gLink, 0);
      sNumVBlanksWithoutSerialIntr = 0;
      sSendNonzeroCheck = 0;
      sRecvNonzeroCheck = 0;
      sChecksumAvailable = 0;
      sHandshakePlayerCount = 0;
      gLastSendQueueCount = 0;
      gLastRecvQueueCount = 0;
}

/** void ResetSerial(void) */
export function ResetSerial(): any {
  EnableSerial();
      DisableSerial();
}

/** u32 LinkMain1(u8 *shouldAdvanceLinkState, u16 *sendCmd, u16 (*recvCmds)[CMD_LENGTH]) */
export function LinkMain1(shouldAdvanceLinkState: any, sendCmd: any): any {
  let retVal: any = null;
      let retVal2: any = null;

      switch (gLink.state)
      {
          case LINK_STATE_START0:
              DisableSerial();
              gLink.state = 1;
              break;
          case LINK_STATE_START1:
              if (shouldAdvanceLinkState == 1)
              {
                  EnableSerial();
                  gLink.state = 2;
              }
              break;
          case LINK_STATE_HANDSHAKE:
              switch (shouldAdvanceLinkState)
              {
                  default:
                      CheckMasterOrSlave();
                      break;
                  case 1:
                      if (gLink.isMaster == (8) && gLink.playerCount > 1)
                          gLink.handshakeAsMaster = TRUE;
                      break;
                  case 2:
                      gLink.state = LINK_STATE_START0;
                      REG_SIOMLT_SEND = 0;
                      break;
              }
              break;
          case LINK_STATE_INIT_TIMER:
              InitTimer();
              gLink.state = LINK_STATE_CONN_ESTABLISHED;
               
          case LINK_STATE_CONN_ESTABLISHED:
              EnqueueSendCmd(sendCmd);
              DequeueRecvCmds(recvCmds);
              break;
      }
      shouldAdvanceLinkState = 0;
      retVal = gLink.localId;
      retVal |= (gLink.playerCount << (2));
      if (gLink.isMaster == (8))
      {
          retVal |= (0x00000020);
      }
      {
          let receivedNothing: any = gLink.receivedNothing << (8);
          let link_field_F: any = gLink.link_field_F << (9);
          let hardwareError: any = gLink.hardwareError << (12);
          let badChecksum: any = gLink.badChecksum << (13);
          let queueFull: any = gLink.queueFull << (14);
          let val: any = null;

          if (gLink.state == LINK_STATE_CONN_ESTABLISHED)
          {
              val = (0x00000040);
              val |= receivedNothing;
              val |= retVal;
              val |= link_field_F;
              val |= hardwareError;
              val |= badChecksum;
              val |= queueFull;
          }
          else
          {
              val = retVal;
              val |= receivedNothing;
              val |= link_field_F;
              val |= hardwareError;
              val |= badChecksum;
              val |= queueFull;
          }

          retVal = val;
      }

      if (gLink.lag == LAG_MASTER)
          retVal |= (0x00010000);

      if (gLink.localId >= (4))
          retVal |= (0x00020000);

      retVal2 = retVal;
      if (gLink.lag == LAG_SLAVE)
          retVal2 |= (0x00040000);

      return retVal2;
}

/** static void CheckMasterOrSlave(void) */
export function CheckMasterOrSlave(): any {
  let terminals: any = null;

      terminals = REG_ADDR_SIOCNT & (SIO_MULTI_SD | SIO_MULTI_SI);
      if (terminals == SIO_MULTI_SD && gLink.localId == 0)
      {
          gLink.isMaster = (8);
      }
      else
      {
          gLink.isMaster = (0);
      }
}

/** static void InitTimer(void) */
export function InitTimer(): any {
  if (gLink.isMaster)
      {
          REG_TM3CNT_L = -197;
          REG_TM3CNT_H = TIMER_64CLK | TIMER_INTR_ENABLE;
          EnableInterrupts(INTR_FLAG_TIMER3);
      }
}

/** static void EnqueueSendCmd(u16 *sendCmd) */
export function EnqueueSendCmd(sendCmd: any): any {
  let i: any = null;
      let offset: any = null;

      gLinkSavedIme = REG_IME;
      REG_IME = 0;
      if (gLink.sendQueue.count < (50))
      {
          offset = gLink.sendQueue.pos + gLink.sendQueue.count;
          if (offset >= (50))
          {
              offset -= (50);
          }
          for (i = 0; i < (8); i++)
          {
              sSendNonzeroCheck |= sendCmd;
              gLink.sendQueue.data[i][offset] = sendCmd;
              sendCmd = 0;
              sendCmd++;
          }
      }
      else
      {
          gLink.queueFull = QUEUE_FULL_SEND;
      }
      if (sSendNonzeroCheck)
      {
          gLink.sendQueue.count++;
          sSendNonzeroCheck = 0;
      }
      REG_IME = gLinkSavedIme;
      gLastSendQueueCount = gLink.sendQueue.count;
}

/** static void DequeueRecvCmds(u16 (*recvCmds)[CMD_LENGTH]) */
export function DequeueRecvCmds(): any {
  let i: any = null;
      let j: any = null;

      gLinkSavedIme = REG_IME;
      REG_IME = 0;
      if (gLink.recvQueue.count == 0)
      {
          for (i = 0; i < gLink.playerCount; i++)
          {
              for (j = 0; j < (8); j++)
              {
                  recvCmds[i][j] = 0;
              }
          }

          gLink.receivedNothing = TRUE;
      }
      else
      {
          for (i = 0; i < gLink.playerCount; i++)
          {
              for (j = 0; j < (8); j++)
              {
                  recvCmds[i][j] = gLink.recvQueue.data[i][j][gLink.recvQueue.pos];
              }
          }
          gLink.recvQueue.count--;
          gLink.recvQueue.pos++;
          if (gLink.recvQueue.pos >= (50))
          {
              gLink.recvQueue.pos = 0;
          }
          gLink.receivedNothing = FALSE;
      }
      REG_IME = gLinkSavedIme;
}

/** void LinkVSync(void) */
export function LinkVSync(): any {
  if (gLink.isMaster)
      {
          switch (gLink.state)
          {
              case LINK_STATE_CONN_ESTABLISHED:
                  if (gLink.serialIntrCounter < 9)
                  {
                      if (gLink.hardwareError != TRUE)
                      {
                          gLink.lag = LAG_MASTER;
                      }
                      else
                      {
                          StartTransfer();
                      }
                  }
                  else if (gLink.lag != LAG_MASTER)
                  {
                      gLink.serialIntrCounter = 0;
                      StartTransfer();
                  }
                  break;
              case LINK_STATE_HANDSHAKE:
                  StartTransfer();
                  break;
          }
      }
      else if (gLink.state == LINK_STATE_CONN_ESTABLISHED || gLink.state == LINK_STATE_HANDSHAKE)
      {
          if (++sNumVBlanksWithoutSerialIntr > 10)
          {
              if (gLink.state == LINK_STATE_CONN_ESTABLISHED)
              {
                  gLink.lag = LAG_SLAVE;
              }
              if (gLink.state == LINK_STATE_HANDSHAKE)
              {
                  gLink.playerCount = 0;
                  gLink.link_field_F = FALSE;
              }
          }
      }
}

/** void Timer3Intr(void) */
export function Timer3Intr(): any {
  StopTimer();
      StartTransfer();
}

/** void SerialCB(void) */
export function SerialCB(): any {
  gLink.localId = SIO_MULTI_CNT.id;
      switch (gLink.state)
      {
          case LINK_STATE_CONN_ESTABLISHED:
              gLink.hardwareError = SIO_MULTI_CNT.error;
              DoRecv();
              DoSend();
              SendRecvDone();
              break;
          case LINK_STATE_HANDSHAKE:
              if (DoHandshake())
              {
                  if (gLink.isMaster)
                  {
                      gLink.state = LINK_STATE_INIT_TIMER;
                      gLink.serialIntrCounter = 8;
                  }
                  else
                  {
                      gLink.state = LINK_STATE_CONN_ESTABLISHED;
                  }
              }
              break;
      }
      gLink.serialIntrCounter++;
      sNumVBlanksWithoutSerialIntr = 0;
      if (gLink.serialIntrCounter == 8)
      {
          gLastRecvQueueCount = gLink.recvQueue.count;
      }
}

/** static void StartTransfer(void) */
export function StartTransfer(): any {
  REG_SIOCNT |= SIO_START;
}

/** static bool8 DoHandshake(void) */
export function DoHandshake(): any {
  let i: any = null;
      let playerCount: any = null;
      let minRecv: any = null;

      playerCount = 0;
      minRecv = 0xFFFF;
      if (gLink.handshakeAsMaster == TRUE)
      {
          REG_SIOMLT_SEND = (0x8FFF);
      }
      else
      {
          REG_SIOMLT_SEND = (0xB9A0);
      }
      gLink.handshakeBuffer = REG_SIOMLT_RECV;
      REG_SIOMLT_RECV = 0;
      gLink.handshakeAsMaster = FALSE;
      for (i = 0; i < (4); i++)
      {
          if ((gLink.handshakeBuffer[i] & ~0x3) == (0xB9A0) || gLink.handshakeBuffer[i] == (0x8FFF))
          {
              playerCount++;
              if (minRecv > gLink.handshakeBuffer[i] && gLink.handshakeBuffer[i] != 0)
                  minRecv = gLink.handshakeBuffer[i];
          }
          else
          {
              if (gLink.handshakeBuffer[i] != 0xFFFF)
                  playerCount = 0;
              break;
          }
      }
      gLink.playerCount = playerCount;
      if (gLink.playerCount > 1 && gLink.playerCount == sHandshakePlayerCount && gLink.handshakeBuffer[0] == (0x8FFF))
      {
          return TRUE;
      }
      if (gLink.playerCount > 1)
      {
          gLink.link_field_F = (minRecv & 3) + 1;
      }
      else
      {
          gLink.link_field_F = 0;
      }
      sHandshakePlayerCount = gLink.playerCount;
      return FALSE;
}

/** static void DoRecv(void) */
export function DoRecv(): any {
  let recv: any = [];
      let i: any = null;
      let index: any = null;

      recv = REG_SIOMLT_RECV;
      if (gLink.sendCmdIndex == 0)
      {
          for (i = 0; i < gLink.playerCount; i++)
          {
              if (gLink.checksum != recv[i] && sChecksumAvailable)
              {
                  gLink.badChecksum = TRUE;
              }
          }
          gLink.checksum = 0;
          sChecksumAvailable = TRUE;
      }
      else
      {
          index = gLink.recvQueue.pos + gLink.recvQueue.count;
          if (index >= (50))
          {
              index -= (50);
          }
          if (gLink.recvQueue.count < (50))
          {
              for (i = 0; i < gLink.playerCount; i++)
              {
                  gLink.checksum += recv[i];
                  sRecvNonzeroCheck |= recv[i];
                  gLink.recvQueue.data[i][gLink.recvCmdIndex][index] = recv[i];
              }
          }
          else
          {
              gLink.queueFull = QUEUE_FULL_RECV;
          }
          gLink.recvCmdIndex++;
          if (gLink.recvCmdIndex == (8) && sRecvNonzeroCheck)
          {
              gLink.recvQueue.count++;
              sRecvNonzeroCheck = 0;
          }
      }
}

/** static void DoSend(void) */
export function DoSend(): any {
  if (gLink.sendCmdIndex == (8))
      {
          REG_SIOMLT_SEND = gLink.checksum;
          if (!sSendBufferEmpty)
          {
              gLink.sendQueue.count--;
              gLink.sendQueue.pos++;
              if (gLink.sendQueue.pos >= (50))
              {
                  gLink.sendQueue.pos = 0;
              }
          }
          else
          {
              sSendBufferEmpty = FALSE;
          }
      }
      else
      {
          if (!sSendBufferEmpty && gLink.sendQueue.count == 0)
          {
              sSendBufferEmpty = TRUE;
          }
          if (sSendBufferEmpty)
          {
              REG_SIOMLT_SEND = 0;
          }
          else
          {
              REG_SIOMLT_SEND = gLink.sendQueue.data[gLink.sendCmdIndex][gLink.sendQueue.pos];
          }
          gLink.sendCmdIndex++;
      }
}

/** static void StopTimer(void) */
export function StopTimer(): any {
  if (gLink.isMaster)
      {
          REG_TM3CNT_H &= ~TIMER_ENABLE;
          REG_TM3CNT_L = -197;
      }
}

/** static void SendRecvDone(void) */
export function SendRecvDone(): any {
  if (gLink.recvCmdIndex == (8))
      {
          gLink.sendCmdIndex = 0;
          gLink.recvCmdIndex = 0;
      }
      else if (gLink.isMaster)
      {
          REG_TM3CNT_H |= TIMER_ENABLE;
      }
}

/** void ResetSendBuffer(void) */
export function ResetSendBuffer(): any {
  let i: any = null;
      let j: any = null;

      gLink.sendQueue.count = 0;
      gLink.sendQueue.pos = 0;
      for (i = 0; i < (8); i++)
      {
          for (j = 0; j < (50); j++)
              gLink.sendQueue.data[i][j] = (0xEFFF);
      }
}

/** void ResetRecvBuffer(void) */
export function ResetRecvBuffer(): any {
  let i: any = null;
      let j: any = null;
      let k: any = null;

      gLink.recvQueue.count = 0;
      gLink.recvQueue.pos = 0;
      for (i = 0; i < (4); i++)
      {
          for (j = 0; j < (8); j++)
          {
              for (k = 0; k < (50); k++)
                  gLink.recvQueue.data[i][j][k] = (0xEFFF);
          }
      }
}

